/* raisetrace: C library for generating stack traces on fault/signal
 * (https://github.com/deimonn/raisetrace) */

#ifndef _RAISETRACE_H
#define _RAISETRACE_H

struct backtrace_state;

/* Perform the default action for the signal/exception on handler return. */
#define RAISETRACE_DEFAULT  0
/* Try to continue execution after the handler returns. */
#define RAISETRACE_CONTINUE 1

/* List of signals/exceptions generated by severe program faults. */
extern const int raisetrace_faults[];
/* List of signals/exceptions generated by sockets, timers or by the user. */
extern const int raisetrace_unhandled[];

/* If set, will be called by the handler installed by raisetrace() when a signal
 * or exception is caught.
 *
 * Receives the signal number or exception code as the first parameter, a
 * message describing the signal or exception as the second, and raisetrace's
 * backtrace_state as the third.
 *
 * If this function returns RAISETRACE_CONTINUE, the handler will try to
 * continue execution of the program. Otherwise it will perform the default
 * action for the signal/exception, which may mean continuing execution or
 * terminating abnormally. */
extern int (*raisetrace_callback)(int num, const char *msg,
                                  struct backtrace_state *state);

/* Install raisetrace's handler for each of the signals/exceptions in the
 * passed list.
 *
 * The handler simply calls raisetrace_callback() if it is not NULL; otherwise,
 * it prints a message and a stack trace (when supported) to the standard error
 * stream and then performs the default action for the signal/exception.
 *
 * The list must be zero-terminated.
 *
 * Returns 0 on success, a negative error number on failure. */
int raisetrace(const int *list);

#endif
